import logging
from builtins import str


logger = logging.getLogger(__name__)


def execute_remote_py_function(function_obj, args_list):

    #     Execute a python function on a remote machine via Squish API.
    #     Limitations:
    #     1) Function cannot reference any other local functions, only library functions;
    #     2) String args functions are handled, provided as list in args_list;
    #     3) Output is via stdout print so function should return printable result.

    import squishtest3 as sq
    hostname = sq.currentApplicationContext().host
    port = sq.currentApplicationContext().port

    from interops.libraries.desktop.configuration import Config
    import interops.libraries.desktop.config_constants as cfg
    import os, sys

    # Get the current python installation path
    python_install_path = sys.exec_prefix
    sharedconfig_path = os.path.abspath(os.path.join(
        python_install_path, cfg.DEFAULT_SHAREDCONFIG_PATH))
    # Load the sharedconfig.cfg file
    Config.load(sharedconfig_path)

    # Get python and temp dir locations from config.
    # Use provided default values otherwise.
    tempDirs = Config.get("system.remote_temp_dir", "D:\\Temp\\")
    pyDirs = Config.get("system.remote_py_dir", "D:\\Squish\\Squish_runtime\\python3")
    try:
        import tempfile
        from remotesystem import RemoteSystem
        import os
        # Store the function source code in a temp file
        src = getFunctionSource(function_obj, args_list)
        f = tempfile.NamedTemporaryFile(delete=False)
        # tempfile's write() expects bytes data. For python 3, convert the string to bytes.
        src_encoded = src.encode('utf-8')
        f.write(src_encoded)
        # Extract file name from tempfile
        src_path = f.name
        src_filename = os.path.basename(src_path)
        f.close()

        remoteOS = RemoteSystem(hostname, port)
        # Make sure we have a temp destination
        tempDir = ""
        tempDirs = tempDirs.split("#")[0].split(";")
        for td in tempDirs:
            td = td.strip()
            tempexists = remoteOS.exists(td)
            if tempexists:
                tempDir = td
                break
        if not tempDir:
            tempDir = tempDirs[0].strip()
            try:
                remoteOS.createDirectory(tempDir)
            except Exception:
                if len(tempDirs) > 1:
                    tempDir = tempDirs[1].strip()
                    remoteOS.createDirectory(tempDir)

        # Upload the tempfile to the target machine as py file.
        remote_py = tempDir + src_filename + ".py"
        remoteOS.upload(src_path, remote_py)
        logger.debug("Uploaded temp py file [" + src_path + "] to [" + remote_py + "]")

        # Execute the file on the target machine
        pyDir = ""
        pyDirs = pyDirs.split("#")[0].split(";")
        for pd in pyDirs:
            pd = pd.strip()
            if remoteOS.exists(pd):
                pyDir = pd
                break
        if not pyDir:
            raise Exception("Remote python not found where expected.")

        cmd = pyDir + "\\python.exe"
        arg = remote_py
        cmdlist = [cmd, arg]
        cmdString = " ".join(cmdlist)
        logger.debug("Remote execute command [" + cmdString + "] on host [" + hostname + "]")

        (exitcode, stdout, stderr) = remoteOS.execute(cmdlist)
        logger.debug("Function " +
                     function_obj.__name__ +
                     " returned: exitcode,exitcode,stderr): " +
                     str((exitcode, stdout, stderr)))
        # Clean up temp files on local and remote machines
        os.remove(src_path)
        remoteOS.deleteFile(remote_py)
        return stdout
    except Exception as e:
        logger.exception(e)


def getFunctionSource(function_obj, args_list):
    #   Get the source code for the given function and append a calling line after the function code.
    import inspect
    lines = list(inspect.getsourcelines(function_obj))
    lines[0].append('\n')
    # For python 3, ensure the print statement has an opening bracket
    lines[0].append('print( ' + function_obj.__name__ + '(')

    first = True

    for arg in args_list:
        # Check if the arg type is a string
        if isinstance(arg, str):
            quote = "'"
        else:
            quote = ""

        if first:
            first = False
            # Note: For python 3, the 'u' prefix is not necessary as strings are unicode by default
            lines[0].append(quote + str(arg) + quote)
        else:
            lines[0].append("," + quote + str(arg) + quote)

    # For python 3, ensure the print statement has a closing bracket
    lines[0].append(')) \n')
    sourceCode = "".join(lines[0])

    return sourceCode
